import { createServer } from 'node:http';
import { mkdir, readFile } from 'node:fs/promises';
import { extname, join, normalize } from 'node:path';
import { fileURLToPath } from 'node:url';
import { DatabaseSync } from 'node:sqlite';

const root = fileURLToPath(new URL('.', import.meta.url));
const publicDirectory = join(root, 'public');
const databasePath = process.env.DB_PATH || join(root, 'data', 'workboard.sqlite');
await mkdir(databasePath.includes('/') ? databasePath.slice(0, databasePath.lastIndexOf('/')) : '.', { recursive: true });
const database = new DatabaseSync(databasePath);
database.exec(`
  CREATE TABLE IF NOT EXISTS projects (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
  )
  ;
  CREATE TABLE IF NOT EXISTS tasks (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    title TEXT NOT NULL,
    completed INTEGER NOT NULL DEFAULT 0,
    created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
  )
`);

const contentTypes = {
  '.css': 'text/css; charset=utf-8',
  '.html': 'text/html; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
};

function sendJson(response, status, body) {
  response.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
  response.end(JSON.stringify(body));
}

async function readJson(request) {
  let body = '';
  for await (const chunk of request) body += chunk;
  return JSON.parse(body || '{}');
}

async function serveStatic(pathname, response) {
  const requestedPath = pathname === '/' || pathname.startsWith('/projects/')
    ? 'index.html'
    : normalize(pathname).replace(/^[/\\]+/, '');
  const filePath = join(publicDirectory, requestedPath);
  if (!filePath.startsWith(`${publicDirectory}/`)) {
    response.writeHead(403).end();
    return;
  }

  try {
    const contents = await readFile(filePath);
    response.writeHead(200, {
      'Content-Type': contentTypes[extname(filePath)] || 'application/octet-stream',
    });
    response.end(contents);
  } catch {
    response.writeHead(404).end('Not found');
  }
}

const server = createServer(async (request, response) => {
  const url = new URL(request.url, 'http://localhost');
  if (url.pathname === '/health' && request.method === 'GET') {
    sendJson(response, 200, { status: 'ok' });
    return;
  }

  if (url.pathname === '/api/projects' && request.method === 'GET') {
    const projects = database.prepare('SELECT id, name FROM projects ORDER BY id').all();
    sendJson(response, 200, projects);
    return;
  }

  if (url.pathname === '/api/projects' && request.method === 'POST') {
    try {
      const { name } = await readJson(request);
      const trimmedName = typeof name === 'string' ? name.trim() : '';
      if (!trimmedName) {
        sendJson(response, 400, { error: 'Project name is required' });
        return;
      }
      const result = database.prepare('INSERT INTO projects (name) VALUES (?)').run(trimmedName);
      sendJson(response, 201, { id: Number(result.lastInsertRowid), name: trimmedName });
    } catch {
      sendJson(response, 400, { error: 'Invalid request' });
    }
    return;
  }

  const projectMatch = url.pathname.match(/^\/api\/projects\/(\d+)$/);
  if (projectMatch && request.method === 'GET') {
    const project = database.prepare('SELECT id, name FROM projects WHERE id = ?').get(Number(projectMatch[1]));
    if (!project) {
      sendJson(response, 404, { error: 'Project not found' });
      return;
    }
    sendJson(response, 200, project);
    return;
  }

  const tasksMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks$/);
  if (tasksMatch && request.method === 'GET') {
    const projectId = Number(tasksMatch[1]);
    const project = database.prepare('SELECT id FROM projects WHERE id = ?').get(projectId);
    if (!project) {
      sendJson(response, 404, { error: 'Project not found' });
      return;
    }
    const tasks = database.prepare('SELECT id, project_id AS projectId, title, completed FROM tasks WHERE project_id = ? ORDER BY id').all(projectId);
    sendJson(response, 200, tasks.map((task) => ({ ...task, completed: Boolean(task.completed) })));
    return;
  }

  if (tasksMatch && request.method === 'POST') {
    try {
      const projectId = Number(tasksMatch[1]);
      const project = database.prepare('SELECT id FROM projects WHERE id = ?').get(projectId);
      if (!project) {
        sendJson(response, 404, { error: 'Project not found' });
        return;
      }
      const { title } = await readJson(request);
      const trimmedTitle = typeof title === 'string' ? title.trim() : '';
      if (!trimmedTitle) {
        sendJson(response, 400, { error: 'Task title is required' });
        return;
      }
      const result = database.prepare('INSERT INTO tasks (project_id, title) VALUES (?, ?)').run(projectId, trimmedTitle);
      sendJson(response, 201, { id: Number(result.lastInsertRowid), projectId, title: trimmedTitle, completed: false });
    } catch {
      sendJson(response, 400, { error: 'Invalid request' });
    }
    return;
  }

  const taskMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks\/(\d+)$/);
  if (taskMatch && request.method === 'PATCH') {
    try {
      const projectId = Number(taskMatch[1]);
      const taskId = Number(taskMatch[2]);
      const { completed } = await readJson(request);
      if (typeof completed !== 'boolean') {
        sendJson(response, 400, { error: 'Completion state is required' });
        return;
      }
      const result = database.prepare('UPDATE tasks SET completed = ? WHERE id = ? AND project_id = ?').run(completed ? 1 : 0, taskId, projectId);
      if (!result.changes) {
        sendJson(response, 404, { error: 'Task not found' });
        return;
      }
      sendJson(response, 200, { id: taskId, projectId, completed });
    } catch {
      sendJson(response, 400, { error: 'Invalid request' });
    }
    return;
  }

  if (request.method === 'GET') {
    await serveStatic(decodeURIComponent(url.pathname), response);
    return;
  }
  sendJson(response, 404, { error: 'Not found' });
});

const port = Number(process.env.PORT || 8080);
server.listen(port, '0.0.0.0');
const app = document.querySelector('#app');

function element(tag, attributes = {}, text = '') {
  const node = document.createElement(tag);
  for (const [name, value] of Object.entries(attributes)) node.setAttribute(name, value);
  if (text) node.textContent = text;
  return node;
}

async function projectsPage() {
  document.title = 'Workboard';
  app.replaceChildren(element('h1', {}, 'Workboard'));

  const form = element('form', { class: 'create-form' });
  const label = element('label', { for: 'project-name' }, 'Project name');
  const input = element('input', { id: 'project-name', name: 'name', type: 'text' });
  const submit = element('button', { type: 'submit' }, 'Create project');
  const alert = element('p', { role: 'alert', class: 'alert' });
  form.append(label, input, submit);
  const list = element('section', { 'aria-label': 'Projects' });
  app.append(form, alert, list);

  async function loadProjects() {
    const response = await fetch('/api/projects');
    const projects = await response.json();
    list.replaceChildren();
    for (const project of projects) {
      const row = element('div', { 'data-testid': 'project-row', class: 'project-row' });
      row.append(element('span', {}, project.name));
      const open = element('button', { type: 'button' }, 'Open project');
      open.addEventListener('click', () => { window.location.href = `/projects/${project.id}`; });
      row.append(open);
      list.append(row);
    }
  }

  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    alert.textContent = '';
    const response = await fetch('/api/projects', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ name: input.value }),
    });
    const result = await response.json();
    if (!response.ok) {
      alert.textContent = result.error || 'Unable to create project';
      return;
    }
    input.value = '';
    await loadProjects();
  });

  await loadProjects();
}

async function projectPage(projectId) {
  const response = await fetch(`/api/projects/${projectId}`);
  if (!response.ok) {
    app.replaceChildren(element('h1', {}, 'Project not found'));
    return;
  }
  const project = await response.json();
  document.title = `${project.name} · Workboard`;
  const back = element('button', { type: 'button' }, 'Projects');
  back.addEventListener('click', () => { window.location.href = '/'; });
  const heading = element('h1', {}, project.name);
  const form = element('form', { class: 'create-form' });
  const label = element('label', { for: 'task-title' }, 'Task title');
  const input = element('input', { id: 'task-title', name: 'title', type: 'text' });
  const submit = element('button', { type: 'submit' }, 'Create task');
  form.append(label, input, submit);
  const alert = element('p', { role: 'alert', class: 'alert' });
  const filterLabel = element('label', { for: 'task-filter' }, 'Task filter');
  const filter = element('select', { id: 'task-filter' });
  for (const option of ['All', 'Open', 'Completed']) {
    filter.append(element('option', { value: option.toLowerCase() }, option));
  }
  const list = element('section', { 'aria-label': 'Tasks' });
  app.replaceChildren(back, heading, form, alert, filterLabel, filter, list);

  async function loadTasks() {
    const tasksResponse = await fetch(`/api/projects/${projectId}/tasks`);
    const tasks = await tasksResponse.json();
    list.replaceChildren();
    for (const task of tasks) {
      if (filter.value === 'open' && task.completed) continue;
      if (filter.value === 'completed' && !task.completed) continue;
      const row = element('div', { 'data-testid': 'task-row', class: 'task-row' });
      const checkbox = element('input', {
        type: 'checkbox',
        'aria-label': `Complete ${task.title}`,
      });
      checkbox.checked = task.completed;
      checkbox.addEventListener('change', async () => {
        await fetch(`/api/projects/${projectId}/tasks/${task.id}`, {
          method: 'PATCH',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ completed: checkbox.checked }),
        });
        await loadTasks();
      });
      row.append(checkbox, element('span', {}, task.title));
      list.append(row);
    }
  }

  filter.addEventListener('change', loadTasks);
  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    alert.textContent = '';
    const createResponse = await fetch(`/api/projects/${projectId}/tasks`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ title: input.value }),
    });
    const result = await createResponse.json();
    if (!createResponse.ok) {
      alert.textContent = result.error || 'Unable to create task';
      return;
    }
    input.value = '';
    await loadTasks();
  });

  await loadTasks();
}

const match = window.location.pathname.match(/^\/projects\/(\d+)\/?$/);
if (match) projectPage(match[1]);
else projectsPage();
